Arguments: {"title":"List all funder cards from aisafety.com/funding","cwd":null,"code":"const tabId = 787783793;

const allFunders = await browserjs(tabId, () => {
  const cards = document.querySelectorAll("a[href]");
  const res = [];
  for (const a of cards) {
    const text = a.innerText.trim();
    if (text.includes("\n") && !a.href.includes("aisafety.com") && !a.href.includes("substack.com")) {
      const lines = text.split("\n").map(s => s.trim()).filter(Boolean);
      res.push({
        title: lines[0],
        desc: lines.slice(1).join(" "),
        url: a.href
      });
    }
  }
  return res;
});

console.log("All funder cards:", allFunders.length);
for (const f of allFunders) {
  console.log(`- ${f.title} | ${f.url}`);
}
"}
